after.content:
  page.on("pageerror", error => errors.push(`${label}:pageerror:${error.message}`))
  page.on("console", message => {
    if (message.type() === "error" && message.text() !== "WebSocket is already in CLOSING or CLOSED state.") {
      const location = message.location().url
      errors.push(`${label}:console:${message.text()}${location ? `:${new URL(location).pathname}` : ""}`)
    }
  })
}
